from dataclasses import dataclass
from datetime import date


@dataclass
class Kitap:
    id: int
    ad: str
    yazar: str


@dataclass
class Uye:
    id: int
    ad: str
    tur: str = "standart"  # "standart" ya da "ogrenci"


@dataclass
class Odunc:
    kitap_id: int
    uye_id: int
    alinma: date
    iade: date | None = None
    ceza: float = 0.0

from .modeller import Odunc
from datetime import date


class KutuphaneServisi:
    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next((k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None), None)

    def _aktif_sayisi(self, uye_id):
        return sum(1 for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

    def _max_odunc(self, uye_id):
        uye = self.uyeler[uye_id]
        if uye.tur == "ogrenci":
            return 5
        return 3

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")
        if self._aktif_sayisi(uye_id) >= self._max_odunc(uye_id):
            raise ValueError(f"{uye_id} numaralı üye maksimum ödünç limitini aşıyor")
        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def ceza_hesapla(self, alinma: date, iade: date, uye_id: int) -> float:
        """Gecikme cezasını hesaplar."""
        gecikme_gunleri = (iade - alinma).days
        if gecikme_gunleri <= 0:
            return 0.0

        gecikme_gunleri = max(0, gecikme_gunleri - 14)  # İlk 14 gün ücretsiz

        ceza = 0.0
        ilk_7_uzunlu = min(gecikme_gunleri, 7)
        sonraki_gunler = gecikme_gunleri - ilk_7_uzunlu

        ceza += ilk_7_uzunlu * 2.50
        ceza += sonraki_gunler * 5.00

        ceza = min(ceza, 150.0)  # Maksimum ceza 150 TL

        uye = self.uyeler[uye_id]
        if uye.tur == "ogrenci":
            ceza *= 0.5

        ceza = round(ceza, 2)
        return ceza

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır, cezayı hesaplar ve ödünç kaydını döndürür."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")
        kayit.iade = tarih
        ceza = self.ceza_hesapla(kayit.alinma, tarih, kayit.uye_id)
        kayit.ceza = ceza
        return kayit

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

    def toplam_ceza(self, uye_id: int) -> float:
        """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
        return sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None)

